// The email half of a play step. The in-process executor already ran
// the step — push rows were written in the action's own transaction and
// this emit is the audit of that, not a claim to claim. This consumer
// turns the same decided send into a mail: one consented fan, the named
// template, the show or release the step is about.
//
// It never chooses a different template, broadens the recipient, or sends
// a step CrowdRelay did not request. First-party steps carry no fan and
// are not mail; the curator wave parks behind `play.step.third_party` and
// is not claimed by serving this lane.
const e = $json;
if (!e || e.type !== 'crowdrelay.play.step_requested' || e.version !== 1) return [];
const d = e.data ?? {};
const NOT_MAIL = new Set(['listing_sweep', 'release_presave_live', 'release_curator_wave']);
if (NOT_MAIL.has(d.step_kind)) return [];
for (const key of ['action_id', 'play_id', 'step_index', 'step_kind', 'template_key', 'fan_id']) {
  if (d[key] === undefined || d[key] === null) throw new Error('play step missing ' + key);
}
const fan = d.fan ?? {};
if (!fan.email || !fan.email.includes('@')) return [];
const event = d.event ?? null;
const release = d.release ?? null;
// A step whose moment has passed is skipped, not sent — a show ask that
// lands after the show is a different, worse message than one not sent.
if (event && event.starts_at && new Date(event.starts_at).getTime() < Date.now()) return [];
return [{ json: {
  event_id: String(e.id),
  action_id: String(d.action_id),
  play_id: String(d.play_id),
  step_index: Number(d.step_index),
  step_kind: String(d.step_kind),
  template_key: String(d.template_key),
  fan_id: String(d.fan_id),
  email: String(fan.email),
  display_name: fan.display_name || '',
  locale: String(fan.locale || ''),
  event_title: event ? String(event.title || '') : '',
  event_venue: event ? String(event.venue || '') : '',
  release_title: release ? String(release.title || '') : '',
  release_link: release ? String(release.link || '') : '',
  call_to_action_url: d.call_to_action_url || null,
}}];

// Render the named template. CrowdRelay chose which step; this lane
// renders it from the supplied facts. A default branch sends the wrong
// message, which is worse than sending none — throw on a key you do not
// know. Polish is the tenant's first language; a fan whose locale is not
// English still reads Polish here.
const p = $input.first().json;
const key = p.template_key;
const pl = !(p.locale || '').toLowerCase().startsWith('en');
const name = p.display_name || '';
const hello = name ? (pl ? 'Czesc ' + name : 'Hi ' + name) : (pl ? 'Czesc' : 'Hi');
const show = p.event_title || '';
const venue = p.event_venue ? (' — ' + p.event_venue) : '';
const link = p.call_to_action_url || p.release_link || 'https://virya.music';
let subject, text;
if (key === 'play.track_us.announce') {
  subject = pl ? ('Nowy koncert: ' + show) : ('New date: ' + show);
  text = [hello + ',', '', pl ? ('Gramy: ' + show + venue + '. Sledz nas, zeby kazda kolejna data dochodzila bez algorytmu:') : ('We play ' + show + venue + '. Track us so every next date reaches you without an algorithm:'), '', link, '', '- VIRYA'].join('\n');
} else if (key === 'play.track_us.post_show') {
  subject = pl ? 'Dziekujemy, ze byles' : 'Thanks for being there';
  text = [hello + ',', '', pl ? ('Wczoraj gralismy ' + show + '. Jesli chcesz slyszec o kazdej kolejnej dacie, sledz nas:') : ('Last night was ' + show + '. To hear about every next date, track us:'), '', link, '', '- VIRYA'].join('\n');
} else if (key === 'play.follow_ask.first') {
  subject = pl ? 'Jedna prosba' : 'One ask';
  text = [hello + ',', '', pl ? 'Sledz nas, zeby kolejne daty dochodzily do Ciebie bez posrednikow:' : 'Track us so the next dates reach you with no middleman:', '', link, '', '- VIRYA'].join('\n');
} else if (key === 'play.follow_ask.second') {
  subject = pl ? 'Jeszcze raz' : 'Once more';
  text = [hello + ',', '', pl ? 'Jedna wiadomosc latwo umknie. Sledz nas, a kolejna data juz nie umknie:' : 'One message is easy to miss. Track us and the next date will not be:', '', link, '', '- VIRYA'].join('\n');
} else if (key === 'play.follow_ask.final') {
  subject = pl ? 'Ostatnia prosba' : 'The last ask';
  text = [hello + ',', '', pl ? 'To ostatni raz, kiedy o to prosimy. Jesli chcesz daty prosto od nas:' : 'This is the last time we ask. If you want dates straight from us:', '', link, '', '- VIRYA'].join('\n');
} else if (key === 'play.dormant_revival.first') {
  subject = pl ? 'Dlugo Cie nie bylo' : 'It has been a while';
  text = [hello + ',', '', pl ? ('Rok minął, a ' + show + ' jest powodem, zeby napisac. Sledz nas, jesli chcesz znowu slyszec:') : ('A year passed, and ' + show + ' is the reason to write. Track us if you want to hear again:'), '', link, '', '- VIRYA'].join('\n');
} else if (key === 'play.dormant_revival.final') {
  subject = pl ? 'Ostatni sygnal' : 'Last signal';
  text = [hello + ',', '', pl ? 'To ostatnia wiadomosc — jesli chcesz zostac, jeden klik wystarczy:' : 'This is the last message — if you want to stay, one click is enough:', '', link, '', '- VIRYA'].join('\n');
} else if (key === 'play.release_runway.audience_announce') {
  subject = pl ? ('Nadchodzi: ' + p.release_title) : ('Coming: ' + p.release_title);
  text = [hello + ',', '', pl ? ('Nasza nowa plyta ' + p.release_title + ' wychodzi wkrotce. Pre-save jest zywy:') : ('Our new release ' + p.release_title + ' is out soon. The pre-save is live:'), '', link, '', '- VIRYA'].join('\n');
} else if (key === 'play.release_runway.release_day_push') {
  subject = pl ? (p.release_title + ' — juz jest') : (p.release_title + ' — out today');
  text = [hello + ',', '', pl ? ('Dzis wychodzi ' + p.release_title + '. Sluchaj tutaj:') : (p.release_title + ' is out today. Listen here:'), '', link, '', '- VIRYA'].join('\n');
} else if (key === 'play.release_runway.sustain_ask') {
  subject = pl ? ('Jeszcze ' + p.release_title) : ('Still ' + p.release_title);
  text = [hello + ',', '', pl ? ('Dwa tygodnie temu wyszla ' + p.release_title + '. Jesli miales/ales wrocic — to ten moment:') : ('Two weeks ago ' + p.release_title + ' came out. If you meant to come back — this is the moment:'), '', link, '', '- VIRYA'].join('\n');
} else {
  throw new Error('Unknown play-step template: ' + key);
}
return [{ json: { ...p, subject, text } }];
